<script setup lang="ts">
import {ref,nextTick} from 'vue'
const steps=['Details','Review','Complete'],current=ref(0),variant=ref('horizontal')
const layoutControl=ref<HTMLSelectElement>()
function move(delta:number){current.value+=delta;if(current.value===0||current.value===steps.length-1)nextTick(()=>layoutControl.value?.focus())}
function reset(){current.value=0;variant.value='horizontal'}
</script>
<template><section class="steps-keys-usage" aria-label="Steps and keyboard keys demonstration"><p>Fictitious local sequence. Continue changes only the indicator; it does not validate, save or complete real work.</p><div class="options"><label>Step layout<select ref="layoutControl" v-model="variant"><option>horizontal</option><option>vertical</option></select></label><button type="button" @click="reset">Reset sample steps</button></div><ol class="steps" :class="variant" aria-label="Sample workflow progress"><li v-for="(step,i) in steps" :key="step" :aria-current="i===current?'step':undefined" :class="{done:i<current,active:i===current}"><span class="number" aria-hidden="true">{{i<current?'✓':i+1}}</span><div><strong>{{step}}</strong><small>{{i<current?'Completed in sample':i===current?'Current sample step':'Upcoming sample step'}}</small></div></li></ol><p role="status">Sample step {{current+1}} of {{steps.length}}: {{steps[current]}}.</p><div class="actions"><button type="button" :disabled="current===0" @click="move(-1)">Back</button><button type="button" :disabled="current===steps.length-1" @click="move(1)">Continue</button></div><h3>Keyboard key styling</h3><p>Use <kbd>Tab</kbd> to move focus, then <kbd>Enter</kbd> or <kbd>Space</kbd> to activate the focused native button.</p><p>Example shortcut notation only: <kbd>Ctrl</kbd> + <kbd>K</kbd> or <kbd>⌘</kbd> + <kbd>K</kbd>. No command palette or custom shortcut is registered by this sample.</p></section></template>
<style scoped>
.steps-keys-usage{padding:20px;margin:20px 0;border:1px solid var(--vp-c-divider);border-radius:12px}.options,.actions{display:flex;flex-wrap:wrap;gap:12px;align-items:end}label{display:flex;flex-direction:column;gap:8px}button,select{min-height:44px;padding:8px 12px;border:1px solid var(--vp-c-divider);border-radius:8px;background:var(--vp-c-bg-soft)}button:disabled{opacity:.55}.steps{display:flex;gap:16px;flex-wrap:wrap;list-style:none!important;padding:0!important;margin:24px 0!important}.steps.vertical{flex-direction:column}.steps li{display:flex;align-items:center;gap:10px;flex:1 1 140px;min-width:0;margin:0!important;padding:12px;border:1px solid var(--vp-c-divider);border-radius:8px;transition:background 160ms ease-out,border-color 160ms ease-out}.vertical li{flex:auto}.steps .active{background:var(--vp-c-brand-soft);border-color:var(--vp-c-brand-1)}.number{display:flex;align-items:center;justify-content:center;width:28px;height:28px;flex-shrink:0;border:1px solid var(--vp-c-divider);border-radius:50%}.steps small{display:block;font-size:12px}.done .number{background:var(--vp-c-bg-soft)}kbd{display:inline-block;padding:2px 6px;border:1px solid var(--vp-c-divider);border-bottom-width:3px;border-radius:5px;background:var(--vp-c-bg-soft);font-size:13px;font-family:var(--vp-font-family-mono)}:focus-visible{outline:3px solid var(--vp-c-brand-1);outline-offset:2px}@media(prefers-reduced-motion:reduce){.steps li{transition:none}}
</style>
